import numpy as np
from scipy.interpolate import CubicSpline,PchipInterpolator
from scipy.ndimage import map_coordinates,gaussian_filter1d
from PIL import Image,ImageDraw
S=.22186
# The five trajectories follow the centre of each calligraphic pen pass.
def spline(nodes,step=.18):
 n=np.array(nodes,float);t=np.r_[0,np.cumsum(np.linalg.norm(np.diff(n,axis=0),axis=1))]
 tt=np.linspace(0,t[-1],max(2,int(t[-1]/step)+1))
 return CubicSpline(t,n)(tt)
def line(a,b):return spline([a,b])
def join(*a):return np.concatenate([a[0]]+[p[1:] for p in a[1:]])
def arch(dx=0):
 p=spline([[389,522],[400,513.4],[410,508.2],[418,507.3],[424,508.7],[427.6,512.6],[427.9,517],[425.5,523],[421,528],[417,533],[413.5,538],[411,543],[408.5,548],[408,553],[410.5,556],[416,556],[425,552]])
 p[:,0]+=dx;return p

def down_up(a,b,c):
 # first u stem, hairline bowl and rising connective
 return spline([a,[a[0]-3,513],[a[0]-7.3,520],[a[0]-13,529],[a[0]-19,538],[a[0]-24,546],[a[0]-27.2,552],b,[b[0]+7,556],[b[0]+17,550],[b[0]+29,540],[c[0]-10,522],c])

def paths():
 p1=join(spline([[360.4,532.1],[374,524.2],[387,515.6],[400,507.4]]),line([400,507.4],[366,555.4]))
 p2=join(arch(),spline([[425,552],[446,539.5],[466,527],[482,516.5],[497.6,507.4]]))
 p3a=down_up([497.6,507.4],[471.5,555.7],[533.5,507.4])
 p3b=spline([[533.5,507.4],[529.5,514],[524,522],[518.5,530],[513,538],[508.5,546],[505.7,552],[507,555.5],[512,556],[522,552.6],[545,538.5],[570,522.9],[595.4,507.4]])
 p3=join(p3a,p3b)
 p4=line([595.4,507.4],[561.5,555.4])
 p5=join(arch(195.3),spline([[620.3,552],[636,542.5],[653.4,532.1]]))
 return [p1,p2,p3,p4,p5]

if __name__=='__main__':
 im=Image.open('/app/target.png'); d=ImageDraw.Draw(im)
 for p,col in zip(paths(),['red','blue','green','orange','magenta']):d.line([tuple(x) for x in p],fill=col,width=1)
 im.crop((350,500,663,565)).resize((1565,325)).save('/app/output/path_overlay.png')
 print('length mm',sum(np.linalg.norm(np.diff(p,axis=0),axis=1).sum() for p in paths())*S)
